function gridHTML() {
  const q = S.q.trim().toLowerCase();
  const list = S.menu.filter(p => (S.cat === 'Tout' || p.category === S.cat) && (!q || (p.name + ' ' + p.description).toLowerCase().includes(q)));
  if (!list.length) return '<div class="empty">Aucun plat ne correspond à ta recherche.</div>';
  return list.map(p => {
    const n = S.cart[p.id] || 0;
    return `<article class="card"><button class="food-photo" data-act="detail" data-id="${esc(p.id)}" aria-label="Voir ${esc(p.name)}"><img src="${esc(p.image || '/assets/food-placeholder.svg')}" alt="${esc(p.name)}" loading="lazy" width="400" height="250"></button><div class="in"><div class="gx-food-title-row"><button class="food-title" data-act="detail" data-id="${esc(p.id)}">${esc(p.name)}</button><button class="gx-fav-btn ${S.favorites.includes(p.id)?'on':''}" data-act="fav-toggle" data-id="${esc(p.id)}" aria-label="${S.favorites.includes(p.id)?'Retirer des':'Ajouter aux'} favoris">${S.favorites.includes(p.id)?'♥':'♡'}</button></div>${p.tag ? `<span class="tag">${esc(p.tag.toUpperCase())}</span>` : ''}<p>${esc(p.description)}</p><span class="gx-rating">${p.review_count?`★ ${Number(p.rating).toFixed(1)} <small>(${p.review_count} avis)</small>`:'Aucun avis pour le moment'}</span><div class="row"><span class="price">${fcfa(unitPrice(p))}${p.promo_price ? ` <del>${fcfa(p.price)}</del>` : ''}</span>${n ? `<span class="qty"><button data-act="dec" data-id="${esc(p.id)}" aria-label="Retirer">−</button><b>${n}</b><button data-act="inc" data-id="${esc(p.id)}" aria-label="Ajouter">+</button></span>` : `<button class="btn btn-sm gx-add-round" data-act="inc" data-id="${esc(p.id)}" aria-label="Ajouter au panier">+</button>`}</div></div></article>`;
  }).join('');
}
