document.addEventListener('change',e=>{if(e.target.id==='profilePhoto'&&e.target.files?.[0]){const img=$('#profilePhotoPreview');img.src=URL.createObjectURL(e.target.files[0]);img.hidden=false;}});
document.addEventListener('input', e => { if (e.target.id === 'q') { S.q = e.target.value; $('#grid').innerHTML = gridHTML(); } if(e.target.id==='gxElectroSearch'){const q=e.target.value.trim().toLocaleLowerCase('fr');const sort=$('#gxElectroSort')?.value||'recent';let items=(S.electronicsSnapshot||[]).filter(p=>(p.name+' '+p.category+' '+(p.description||'')).toLocaleLowerCase('fr').includes(q));if(sort==='price-asc')items.sort((a,b)=>a.price-b.price);else if(sort==='price-desc')items.sort((a,b)=>b.price-a.price);else if(sort==='name')items.sort((a,b)=>a.name.localeCompare(b.name,'fr'));const catalog=$('#gx-electro-catalog');if(catalog)catalog.innerHTML=items.map(electronicCard).join('')||'<div class="panel empty">Aucun produit ne correspond à ta recherche.</div>';}});
document.addEventListener('change',e=>{if(e.target.id==='gxElectroSort'){const search=$('#gxElectroSearch');if(search)search.dispatchEvent(new Event('input',{bubbles:true}));}});
document.addEventListener('submit', async e => {
  e.preventDefault(); const f = e.target, v = Object.fromEntries(new FormData(f)); const btn = f.querySelector('[type=submit]'); btn.disabled = true;
  try {
    if (f.id === 'reviewForm') { const [itemType,itemId]=(v.itemTarget||'general|').split('|');const r=await api('/reviews',{method:'POST',body:{rating:Number(v.rating),comment:v.comment,itemType,itemId}});toast(r.message);go('#/avis');nav(); } else if (f.id === 'assistantForm') { const hist=$('#assistantHistory'); hist.insertAdjacentHTML('beforeend',`<div class="assistant-bubble mine">${esc(v.message)}</div>`); const question=v.message; f.reset(); const wait=document.createElement('div');wait.className='assistant-bubble';wait.textContent='Je recherche une réponse…';hist.append(wait);try{const r=await api('/assistant',{method:'POST',body:{message:question}});wait.textContent=r.answer;}catch(err){wait.textContent=err.message;} hist.scrollTop=hist.scrollHeight; } else if (f.id === 'authForm') {
      let body = v; if(S.mode==='register'){if(v.password!==v.confirmPassword)throw new Error('Les deux mots de passe ne correspondent pas.');const file=$('#profilePhoto')?.files?.[0];if(!file)throw new Error('Ajoute une photo de profil.');if(file.size>2*1024*1024)throw new Error('Photo limitée à 2 Mo.');const profileImage=await new Promise((resolve,reject)=>{const rd=new FileReader();rd.onload=()=>resolve(rd.result);rd.onerror=()=>reject(new Error('Lecture de la photo impossible.'));rd.readAsDataURL(file)});body={...v,profileImage,acceptTerms:!!v.acceptTerms};}
      const r = await api('/auth/' + S.mode, { method: 'POST', body }); S.user = r.user; await refreshMe();
      toast('Bienvenue ' + S.user.name + ' !'); const nx = S.next || '#/'; S.next = null; go(nx); nav();
    } else if (f.id === 'orderForm') {
      if (!S.user) { S.next = '#/panier'; S.mode = 'login'; vAuth(); return; }
      store.set('gx_pickup', v.pickup);
      const o = await api('/orders', { method: 'POST', body: { pickup: v.pickup, note: v.note, paymentMethod:v.paymentMethod||'pickup', paymentPhone:v.paymentPhone||'', promoCode:S.promo?.code||'', items: Object.entries(S.cart).map(([id, qty]) => ({ id, qty })) } });
      const statuses = store.get('gx_order_statuses', {}); statuses[o.ref] = 'received'; store.set('gx_order_statuses', statuses);
      S.cart = {}; S.promo=null; saveCart(); toast('Commande ' + o.ref + ' envoyée !'); go('#/commande/' + o.ref);
    } else if (f.id === 'profileForm') { const r = await api('/me', { method: 'PATCH', body: v }); S.user = r.user; toast('Informations enregistrées.'); }
    else if (f.id === 'pwForm') { await api('/me/password', { method: 'POST', body: v }); f.reset(); toast('Mot de passe modifié.'); }
  } catch (err) { fail(f.id === 'pwForm' ? '#msg2' : '#msg', err); }
  finally { btn.disabled = false; }
});

// ---------- Démarrage ----------
async function refreshMe() { const r = await api('/me').catch(() => ({})); S.user = r.user || null; S.loyalty = r.loyalty || null; }
async function init() {
  saveCart();
  const [cfg, menu, hero] = await Promise.all([api('/config').catch(() => null), api('/menu').catch(() => null), api('/hero-images').catch(()=>null), refreshMe()]);
  if(hero?.images)S.heroImages=hero.images;
  if (cfg) { S.cfg = cfg; const s = $('#sosLink'); s.href = 'tel:+225' + cfg.emergency; s.textContent = 'Assistance ' + cfg.emergency.replace(/(\d{2})(?=\d)/g, '$1 ').trim(); }
  if (menu) { S.menu = menu.products; S.cats = menu.categories; S.categoryIcons=menu.categoryIcons||{}; for (const id of Object.keys(S.cart)) if (!S.menu.some(m => m.id === id)) delete S.cart[id]; saveCart(); }
  else toast('Menu indisponible : vérifie ta connexion.');
  nav();
  refreshNotificationCount();
  const refreshSharedCatalogues=async()=>{if(document.hidden)return;refreshNotificationCount();try{const [m,e]=await Promise.all([api('/menu'),api('/electronics')]);const changed=JSON.stringify(m.products)!==JSON.stringify(S.menu)||JSON.stringify(m.categoryIcons||{})!==JSON.stringify(S.categoryIcons||{})||JSON.stringify(e.products)!==JSON.stringify(S.electronicsSnapshot)||JSON.stringify(e.banners)!==JSON.stringify(S.electronicsBannersSnapshot)||JSON.stringify(e.categories)!==JSON.stringify(S.electronicsCategoriesSnapshot);if(changed){S.menu=m.products;S.cats=m.categories;S.categoryIcons=m.categoryIcons||{};S.electronicsSnapshot=e.products;S.electronicsBannersSnapshot=e.banners;S.electronicsCategoriesSnapshot=e.categories;}const route=location.hash;if(changed&&(route.startsWith('#/electronique')||route==='#/'||route==='#')||route.startsWith('#/commandes')||route.startsWith('#/notifications')||route.startsWith('#/profil'))nav();}catch{}};
  if('EventSource' in window){const live=new EventSource('/api/events');live.addEventListener('data-change',refreshSharedCatalogues);live.addEventListener('open',refreshSharedCatalogues);window.addEventListener('pagehide',()=>live.close(),{once:true});}else{setInterval(refreshSharedCatalogues,8000);}
  startReadyChecks();
  maybeInstallNudge();
}
